const fmt = (iso, tz, locale) => new Date(iso).toLocaleString(locale, { timeZone: tz || 'Europe/Warsaw', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const rawEmail = (to, subject, body) => Buffer.from(
  [`To: ${to}`, `Subject: =?UTF-8?B?${b64(subject)}?=`, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64'].join('\r\n') +
  '\r\n\r\n' + b64(body)).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// One reminder per viewing tomorrow (0038). WhatsApp when the client wrote on
// WhatsApp (template 'viewing_reminder', so it arrives outside the 24-hour
// window), otherwise email. Calls with the Elliot team: email with the Meet link.
const r = $json;
const tz = r.timezone || 'Europe/Warsaw';
const polish = /[ąćęłńóśźż]|\b(dzień|dobry|mieszkanie|prezentacj|proszę|dziękuję|cześć|witam|jutro)\b/i.test(r.last_client_message || '');
const lang = r.last_client_message ? (polish ? 'pl' : 'en') : 'pl';
const isCall = r.assistant_mode === 'sales';
const first = String(r.contact_name || '').trim().split(/\s+/)[0] || '';
const time = (loc) => new Date(r.starts_at).toLocaleTimeString(loc, { timeZone: tz, hour: '2-digit', minute: '2-digit' });
const day = (loc) => new Date(r.starts_at).toLocaleDateString(loc, { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long' });
// 0043: a valuation visit happens at the client's own address.
const isValuation = r.kind === 'valuation';
const place = isValuation ? String(r.location || '') : [r.listing_title, r.listing_address].filter(Boolean).join(', ');
const meet = ((r.notes || '').match(/Google Meet: (\S+)/) || [])[1] || null;
const phone = String(r.contact_phone || '').replace(/\D/g, '');
const useWhatsApp = !isCall && !isValuation && r.conversation_channel === 'whatsapp' && phone.length >= 8 && !!r.whatsapp_phone_number_id;
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(r.contact_email || '')) ? r.contact_email : null;

const en = isValuation
  ? `Reminder: an agent from ${r.tenant_name} is coming tomorrow, ${day('en-GB')} at ${time('en-GB')}, to value your property${place ? ` at ${place}` : ''}. Reply to confirm, or tell us if you need to change or cancel it.`
  : isCall
  ? `Reminder: your call with Elliot is tomorrow, ${day('en-GB')} at ${time('en-GB')} (Warsaw time).${meet ? ` Google Meet: ${meet}` : ''} Reply if you need another time.`
  : `Reminder: your viewing with ${r.tenant_name} is tomorrow, ${day('en-GB')} at ${time('en-GB')}${place ? `, ${place}` : ''}. Reply to confirm, or tell us if you need to change or cancel it.`;
const pl = isValuation
  ? `Przypomnienie: jutro, ${day('pl-PL')}, o ${time('pl-PL')} agent ${r.tenant_name} przyjedzie wycenić nieruchomość${place ? ` (${place})` : ''}. Prosimy o potwierdzenie albo informację, jeśli trzeba zmienić lub odwołać termin.`
  : isCall
  ? `Przypomnienie: rozmowa z Elliot jutro, ${day('pl-PL')}, o ${time('pl-PL')}.${meet ? ` Google Meet: ${meet}` : ''} Jeśli potrzebny jest inny termin, prosimy o odpowiedź.`
  : `Przypomnienie: prezentacja z ${r.tenant_name} jutro, ${day('pl-PL')}, o ${time('pl-PL')}${place ? `, ${place}` : ''}. Prosimy o potwierdzenie albo informację, jeśli trzeba zmienić lub odwołać termin.`;
const logText = lang === 'pl' ? pl : en;

let out = { appointment_id: r.appointment_id, tenant_id: r.tenant_id, conversation_id: r.conversation_id || null, log_text: logText, email };
if (useWhatsApp) {
  out = { ...out, channel: 'whatsapp', to: phone, sender_id: r.whatsapp_phone_number_id, lang,
    params: [first || (lang === 'pl' ? 'Państwo' : 'there'), r.tenant_name, `${day(lang === 'pl' ? 'pl-PL' : 'en-GB')}, ${time('en-GB')}`, place || (lang === 'pl' ? 'adres w potwierdzeniu' : 'see your confirmation')]
      .map((p) => String(p).replace(/\s+/g, ' ').trim().slice(0, 200)) };
} else if (email) {
  out = { ...out, channel: 'email' };
} else {
  out = { ...out, channel: 'none' };
}
if (email) {
  const subject = isValuation ? `Reminder: valuation visit tomorrow at ${time('en-GB')}` : isCall ? `Reminder: your call with Elliot tomorrow at ${time('en-GB')}` : `Reminder: viewing tomorrow at ${time('en-GB')}${r.listing_title ? ' – ' + r.listing_title : ''}`;
  const body = `Hi${first ? ' ' + first : ''},\n\n${en}\n\n${isCall ? 'The Elliot team' : r.tenant_name}\n\n----------------------------------------\n\nDzień dobry${first ? ' ' + first : ''},\n\n${pl}\n\n${isCall ? 'The Elliot team' : r.tenant_name}\n`;
  out.raw_message = rawEmail(email, subject, body);
}
return { json: out };

// Meta accepted the template? If not and there's an email, the email goes instead.
const r = $json;
const b = $('Build Reminder').item.json;
const st = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const err = body && body.error;
const ok = st >= 200 && st < 300 && !err;
const why = ok ? '' : (err ? `${err.message || 'refused'}${err.code ? ` (code ${err.code})` : ''}` : `HTTP ${st || 'no response'}`);
return { json: { ...b, ok, channel: ok ? 'whatsapp' : b.channel, error: why, fallback: !ok && !!b.email } };

// Workflow 39 answered 2xx = sent.
const r = $json;
const b = $('Build Reminder').item.json;
const st = Number(r.statusCode || 0);
const ok = st >= 200 && st < 300;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
return { json: { ...b, ok, channel: 'email', error: ok ? '' : ((body && body.error && body.error.message) || `HTTP ${st || 'no response'}`) } };

parameters.query:
-- Sent: logged into the conversation (so a reply has context). Failed: audit log,
-- which the health alerts (workflow 33) pick up. No contact details: marked as done.
select record_viewing_reminder($1::uuid, $2, $3::boolean, $4, nullif($5, '')::uuid);
